<script setup lang="ts">
import {computed,ref} from 'vue'
import {useStudio} from './studioContext'
const props=defineProps<{page:string,label?:string}>(),s=useStudio(),working=ref(false)
const job=computed(()=>s.p.value?.workspace.jobs?.find((j:any)=>j.family==='completion'&&j.scope===props.page))
async function control(action:string){if(!job.value)return;working.value=true;try{await s.run(async()=>{await s.syncLatest();await s.api(`/projects/${s.p.value.id}/studio/completions/${job.value.id}/${action}`,'POST',{version:s.p.value.version,requestId:crypto.randomUUID()});await s.syncLatest()})}finally{working.value=false}}
</script>
<template><div class="completion-control"><button class="primary" :disabled="working||s.busy.value||s.generating.value||!s.p.value" @click="s.complete(page)">{{label||'一键完成本页'}}（调用模型）</button><template v-if="job"><span v-if="['queued','running'].includes(job.state)" role="status">{{job.progress}}</span><button v-if="['queued','running'].includes(job.state)" :disabled="working" @click="control('cancel')">取消，保留已完成内容</button><template v-else-if="['failed','interrupted','partial'].includes(job.state)"><button :disabled="working||s.generating.value" @click="control('continue')">继续未完成步骤</button><details><summary>查看具体问题</summary><p>{{job.error}}</p><p v-for="step in job.steps.filter((v:any)=>v.message)">{{step.label||step.stage}}：{{step.message}}</p></details></template><template v-else-if="job.state==='completed'"><small>已完成 · 可交谈{{job.capabilities?.chatCharacters||0}}位 · 分镜{{job.capabilities?.storyboards||0}}个</small><details v-if="job.steps?.some((v:any)=>v.notes?.length)"><summary>部分条目未启用，其他内容可继续使用</summary><template v-for="step in job.steps"><p v-for="note in step.notes||[]">{{note.key}}：{{note.message}}</p></template></details></template></template></div></template>
<style scoped>.completion-control{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:8px;max-width:620px}.completion-control>span,.completion-control small,.completion-control details{font-size:11px;color:#74827b}.completion-control>span{max-width:280px}.completion-control details p{max-width:500px;font-size:12px}.completion-control>button{white-space:nowrap}</style>
